161	  if (!ev.matched) return { state: ev.error ? 'error' : 'notfound', error: ev.error };
162	  const t = ev.traces[0];
163	  const s = t.summary;
164	  const text = [
165	    `trace ${s.traceId} · ${s.status} · ${s.spans} spans · ${s.toolCalls} tool calls · ${s.errors.length} failed`,
166	    ...s.sequence.map((x) => `  - ${x.name}${x.n > 1 ? ` x${x.n}` : ''}${x.error ? ' (error)' : ''}`),
167	  ].join('\n').slice(0, 4000);
168	  return { state: 'read', sessionId, summary: s, text };
169	}
