221	  fs.mkdirSync(dir, { recursive: true });
222	  const verdictFile = path.join(dir, 'verdict.json');
223	  const testPlanFile = path.join(mod.repoDir, 'playtest', 'test-plan.json');
224	  fs.rmSync(verdictFile, { force: true });
225	
226	  if (game.status().mock) {
227	    const v = game.mockVerdict(mod.testPlan, attempt.n);
228	    fs.writeFileSync(verdictFile, JSON.stringify(v, null, 2));
229	    feed(mod, { attempt: attempt.n, role: 'playtester', kind: 'note', text: '[mock runtime] canned verdict' });
230	    return game.readVerdict(verdictFile, mod.testPlan);
231	  }
232	
233	  for (let run = 1; run <= 2; run++) {
234	    const mcpFile = path.join(studioDir, mod.id, `mcp-attempt-${attempt.n}.json`);
235	    fs.mkdirSync(path.dirname(mcpFile), { recursive: true });
236	    fs.writeFileSync(mcpFile, JSON.stringify(game.mcpConfig({ runId: `${mod.id}_${attempt.n}`, verdictFile, testPlanFile })));
237	    const poll = setInterval(() => {
238	      if (!fs.existsSync(verdictFile)) return;
239	      const live = game.readVerdict(verdictFile, mod.testPlan);
240	      attempt.verdict = { ...live, live: true };
241	      save(mod);
242	    }, 1000);
243	    try {
244	      await agent(mod, attempt, 'playtester', { cwd: mod.repoDir, prompt: game.playtestPrompt(mod.testPlan), model: MODELS.playtest, tools: [], allowedTools: game.playtesterTools, mcpConfigFile: mcpFile });
245	    } finally {
246	      clearInterval(poll);
247	    }
248	    const verdict = game.readVerdict(verdictFile, mod.testPlan);
249	    if (verdict.finished) return verdict;
250	    feed(mod, { attempt: attempt.n, role: 'benana', kind: 'note', text: run === 1 ? 'The playtester stopped before finishing; running it again.' : 'The playtester did not finish the test plan.' });
