255	// Attempt numbers run across the whole chat (playtest folders and the UI key on them); `previous` is null for a turn's first attempt.
256	async function runAttempt(mod, turnIndex, n, previous) {
257	  const turn = mod.turns[turnIndex];
258	  const first = !previous;
259	  const attempt = {
260	    n, turn: turnIndex, revision: first && Boolean(turn.revision),
261	    role: !first ? 'fixer' : mod.seed && !turn.revision ? 'seeded' : 'builder',
262	    status: 'running', startedAt: now(), sessions: [],
263	  };
264	  mod.attempts.push(attempt);
265	  save(mod);
266	
267	  setPhase(mod, first ? 'build' : 'fix', !first ? `Attempt ${n}: fixing what the playtester found` : `Attempt ${n}: ${attempt.revision ? 'changing' : 'writing'} ${mod.name}`);
268	  await codePhase(mod, attempt, previous);
269	
270	  setPhase(mod, 'compile', `Attempt ${n}: compiling with Maven`);
271	  attempt.build = await repo.build(mod.repoDir, mod.name);
272	  if (!attempt.build.ok) {
273	    attempt.failure = { kind: 'build', summary: 'The plugin did not compile.' };
274	    attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): build failed`);
275	    return attempt;
276	  }
277	  const did = attempt.role === 'fixer' ? `fix ${mod.name} from playtest evidence` : attempt.revision ? `change ${mod.name}: ${turn.prompt.replace(/\s+/g, ' ').slice(0, 72)}` : `implement ${mod.name}`;
278	  attempt.commit = await repo.commit(mod.repoDir, `Attempt ${n} (${attempt.role}): ${did}`);
279	  feed(mod, { attempt: n, role: 'benana', kind: 'note', text: `Committed ${attempt.commit.sha.slice(0, 7)}${attempt.commit.checkpoint ? `, Entire checkpoint ${attempt.commit.checkpoint}` : ''}` });
280	
281	  setPhase(mod, 'deploy', `Attempt ${n}: deploying to the Paper server`);
282	  attempt.deploy = await game.deployPlugin({ jarPath: attempt.build.jar, emit });
283	  if (!attempt.deploy.loaded) {
284	    attempt.failure = { kind: 'load', summary: 'The plugin did not load on the server.' };
285	    return attempt;
286	  }
287	
288	  setPhase(mod, 'playtest', `Attempt ${n}: the AI player is testing ${mod.name} in-game`);
289	  attempt.verdict = await playtestPhase(mod, attempt);
290	  const tally = attempt.verdict.checks.map((c) => `${c.id}=${c.status}`).join(', ');
291	  attempt.playtestCommit = await repo.commit(mod.repoDir, `Playtest attempt ${n}: ${attempt.verdict.passed ? 'PASS' : 'FAIL'}${tally ? ` (${tally})` : ''}`);
292	  if (!attempt.verdict.passed) {
293	    const failed = attempt.verdict.checks.filter((c) => c.status !== 'pass');
294	    attempt.failure = attempt.verdict.finished
295	      ? { kind: 'playtest', summary: failed.length ? failed.map((c) => `${c.id}: ${c.observed}`).join(' · ') : `${attempt.verdict.serverErrors.length} server error(s)` }
296	      : { kind: 'playtest', summary: attempt.verdict.error || 'The playtester did not finish.' };
297	  }
298	  return attempt;
299	}
