301	// Runs the mod's latest turn. The first turn builds the plugin from scratch; a revision turn (the repository already exists)
302	// updates the spec and test plan, changes the existing code, and playtests it again.
303	async function run(mod) {
304	  const turnIndex = mod.turns.length - 1;
305	  const turn = mod.turns[turnIndex];
306	  active = { modId: mod.id, stop: () => {}, stopped: false };
307	  // Records how the turn ended so older turns keep their own result once the chat moves on.
308	  const settle = (status, done) => {
309	    mod.status = status;
310	    turn.status = status;
311	    if (done) setPhase(mod, 'done', done);
312	    turn.endPhase = mod.phase;
313	  };
314	  try {
315	    if (game.status().bot !== 'online' && !game.status().mock) {
316	      setPhase(mod, 'game', 'Starting the Minecraft server');
317	      await game.start(emit);
318	    }
319	    mod.status = 'running';
320	    mod.error = null;
321	    setPhase(mod, 'spec', turn.revision ? 'Updating the spec and test plan for your change' : 'Writing the spec and an in-game test plan');
322	    const spec = await specPhase(mod, turn);
323	    mod.name = spec.modName;
324	    mod.spec = { summary: spec.summary, behavior: spec.behavior || [] };
325	    mod.testPlan = spec.testPlan;
326	    Object.assign(turn, { summary: spec.summary, checks: spec.testPlan.checks });
327	    feed(mod, { role: 'spec', kind: 'plan', text: `${mod.testPlan.checks.length} checks: ${mod.testPlan.checks.map((c) => c.title).join(' · ')}` });
328	
329	    if (turn.revision) {
330	      fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
331	      fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
332	      await repo.commit(mod.repoDir, 'Update the in-game test plan');
333	    } else {
334	      setPhase(mod, 'repo', 'Creating the mod repository with Entire and Neatlogs hooks');
335	      const created = await repo.create({ slug: `${slugify(mod.name)}-${mod.id.slice(-4)}`, name: mod.name, summary: mod.spec.summary });
336	      mod.repoDir = created.dir;
337	      mod.partners = created.partners;
338	      fs.mkdirSync(path.join(mod.repoDir, 'playtest'), { recursive: true });
339	      fs.writeFileSync(path.join(mod.repoDir, 'playtest', 'test-plan.json'), JSON.stringify(mod.testPlan, null, 2));
340	      await repo.commit(mod.repoDir, 'Add the in-game test plan');
341	    }
342	    save(mod);
343	
344	    let previous = null;
345	    const firstN = (mod.attempts.at(-1)?.n ?? 0) + 1;
346	    for (let n = firstN; n < firstN + MAX_ATTEMPTS; n++) {
347	      const attempt = await runAttempt(mod, turnIndex, n, previous);
348	      attempt.status = attempt.failure ? 'failed' : 'passed';
349	      attempt.endedAt = now();
350	      save(mod);
351	      if (!attempt.failure) {
352	        if (attempt.lesson) addLesson(attempt.lesson, mod);
353	        const used = n - firstN + 1;
354	        settle('passed', used === 1 ? `${mod.name} passed every check on the first attempt` : `${mod.name} passed after ${used} attempts`);
355	        return;
356	      }
357	      feed(mod, { attempt: n, role: 'benana', kind: 'failure', text: `Attempt ${n} failed (${attempt.failure.kind}): ${attempt.failure.summary}` });
358	      previous = attempt;
359	    }
360	    settle('failed', `${mod.name} still fails after ${MAX_ATTEMPTS} attempts`);
361	  } catch (e) {
362	    settle(active?.stopped ? 'stopped' : 'failed');
363	    mod.error = e.message;
364	    feed(mod, { role: 'benana', kind: 'error', text: e.message });
365	    log(`studio: ${e.message}`, 'error');
366	    save(mod);
367	  } finally {
368	    active = null;
369	    save(mod);
370	  }
371	}
