478	/**
479	 * @returns {{ done: Promise<{ok, sessionId, final, usage, error}>, stop: () => void }}
480	 */
481	function runClaude({ cwd, prompt, model, tools, allowedTools = [], mcpConfigFile, appendSystemPrompt, timeoutMs = 20 * 60 * 1000, onEvent = () => {} }) {
482	  const args = ['-p', '--output-format', 'stream-json', '--verbose', '--model', model, '--permission-mode', 'acceptEdits', '--setting-sources', 'project,local'];
483	  if (tools) args.push('--tools', tools.join(','));
484	  if (allowedTools.length) args.push('--allowedTools', allowedTools.join(','));
485	  if (mcpConfigFile) args.push('--mcp-config', mcpConfigFile, '--strict-mcp-config');
486	  if (appendSystemPrompt) args.push('--append-system-prompt', appendSystemPrompt);
487	
488	  const env = { ...process.env };
489	  delete env.ELECTRON_RUN_AS_NODE;
490	  const child = spawnExecutable('claude', args, { cwd, stdio: ['pipe', 'pipe', 'pipe'], env });
491	  const run = { sessionId: null, final: '', usage: null, error: null, stopped: false };
492	  const names = new Map();
493	
494	  const done = new Promise((resolve) => {
495	    let buf = '';
496	    let stderr = '';
497	    const timer = setTimeout(() => { run.error = `Timed out after ${Math.round(timeoutMs / 60000)} minutes.`; terminateProcessTree(child); }, timeoutMs);
498	    const handle = (line) => {
499	      let ev;
500	      try { ev = JSON.parse(line); } catch { return; }
501	      if (ev.type === 'system' && ev.session_id) {
502	        if (!run.sessionId) onEvent({ kind: 'session', sessionId: ev.session_id, model });
503	        run.sessionId = ev.session_id;
504	      } else if (ev.type === 'assistant') {
505	        for (const item of ev.message?.content || []) {
506	          if (item.type === 'text' && item.text.trim()) onEvent({ kind: 'text', text: item.text.trim() });
507	          if (item.type === 'tool_use') {
508	            names.set(item.id, item.name);
509	            onEvent({ kind: 'tool', name: item.name.replace(/^mcp__\w+?__/, ''), input: item.input, summary: summarize(item.input) });
510	          }
511	        }
512	      } else if (ev.type === 'user') {
513	        for (const item of ev.message?.content || []) {
514	          if (item.type !== 'tool_result') continue;
515	          const name = (names.get(item.tool_use_id) || 'tool').replace(/^mcp__\w+?__/, '');
516	          onEvent({ kind: 'result', name, isError: Boolean(item.is_error), text: resultText(item.content).slice(0, 1500) });
517	        }
518	      } else if (ev.type === 'result') {
519	        run.final = ev.result || '';
520	        run.usage = normalizeUsage(ev.usage, ev);
521	        if (ev.is_error) run.error = String(ev.result || 'Claude reported an error.');
522	      }
523	    };
524	    child.stdout.on('data', (d) => {
525	      buf += d;
526	      const lines = buf.split(/\r?\n/);
527	      buf = lines.pop();
528	      lines.filter(Boolean).forEach(handle);
529	    });
530	    child.stderr.on('data', (d) => { stderr = (stderr + d).slice(-4000); });
531	    child.on('error', (e) => { run.error = `Could not start Claude Code: ${e.message}`; });
532	    child.on('close', (code) => {
533	      clearTimeout(timer);
534	      if (buf.trim()) handle(buf);
535	      if (run.stopped) run.error = 'Stopped.';
536	      else if (code !== 0 && !run.error) run.error = stderr.trim() || `Claude exited with code ${code}.`;
537	      resolve({ ok: !run.error, sessionId: run.sessionId, final: run.final, usage: run.usage, error: run.error });
538	    });
539	  });
540	
541	  child.stdin.end(prompt);
542	  return { done, stop: () => { run.stopped = true; terminateProcessTree(child); } };
543	}
