557	function exec(cmd, args, cwd, { timeoutMs = 120000, input } = {}) {
558	  return new Promise((resolve) => {
559	    const bin = resolveExecutable(cmd);
560	    // npm and Maven install .cmd shims on Windows, which only run through a shell. Their args here have no spaces.
561	    const shell = /\.(cmd|bat)$/i.test(bin);
562	    const child = execFile(shell ? `"${bin}"` : bin, args, { cwd, shell, timeout: timeoutMs, maxBuffer: 32 * 1024 * 1024, windowsHide: true, env: { ...process.env, ACCESSIBLE: '1' } },
563	      (error, stdout, stderr) => resolve({
564	        ok: !error,
565	        code: error?.code ?? 0,
566	        out: String(stdout || ''),
567	        err: String(stderr || error?.message || ''),
568	        missing: error?.code === 'ENOENT',
569	      }));
570	    child.stdin.end(input ?? '');
571	  });
572	}
