580	function copyTemplate(dir, vars) {
581	  const walk = (src, dst) => {
582	    fs.mkdirSync(dst, { recursive: true });
583	    for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
584	      const from = path.join(src, entry.name);
585	      const name = entry.name === 'gitignore' ? '.gitignore' : fill(entry.name, vars);
586	      const to = path.join(dst, name);
587	      if (entry.isDirectory()) walk(from, to);
588	      else fs.writeFileSync(to, fill(fs.readFileSync(from, 'utf8'), vars));
589	    }
590	  };
591	  walk(TEMPLATE, dir);
592	}
