665	async function build(dir, name) {
666	  const res = await exec('mvn', ['-q', '-B', 'package'], dir, { timeoutMs: 6 * 60 * 1000 });
667	  const log = `${res.out}\n${res.err}`.trim();
668	  const jar = path.join(dir, 'target', `${name}.jar`);
669	  if (res.missing) return { ok: false, jar: null, log: 'Maven (mvn) is not on PATH.' };
670	  return { ok: res.ok && fs.existsSync(jar), jar: fs.existsSync(jar) ? jar : null, log: log.slice(-12000) };
671	}
