121	    samples.push({ tick, pos: vec(e.position), vel: vec(e.velocity), dpos: vec(dp) });
122	  }
123	  const live = samples.filter((s) => s.pos);
124	  return {
125	    entityId: e.id,
126	    name: e.name,
127	    // Server velocity packets are exact; position updates arrive batched every few ticks.
128	    maxUpwardVelocity: round(Math.max(0, ...live.map((s) => s.vel[1]))),
129	    maxHeightGain: round(Math.max(0, ...live.map((s) => s.pos[1] - start.y))),
130	    start: vec(start),
131	    end: live.length ? live[live.length - 1].pos : null,
132	    samples,
