151	// Simulates the projectile for each pitch and keeps the flattest one that lands on the target.
152	function aim(from, to, speed, gravity) {
153	  const dx = to.x - from.x;
154	  const dz = to.z - from.z;
155	  const dy = to.y - from.y;
156	  const dist = Math.hypot(dx, dz);
157	  let best = null;
158	  for (let deg = -40; deg <= 45; deg += 0.25) {
159	    const t = (deg * Math.PI) / 180;
160	    let vx = Math.cos(t) * speed;
161	    let vy = Math.sin(t) * speed;
162	    let x = 0;
163	    let y = 0;
164	    for (let i = 0; i < 200 && x < dist; i++) {
165	      if (x + vx >= dist) { y += (vy * (dist - x)) / vx; x = dist; break; }
166	      x += vx;
167	      y += vy;
168	      vx *= 0.99;
169	      vy = vy * 0.99 - gravity;
170	    }
171	    if (x < dist) continue;
172	    const err = Math.abs(y - dy);
173	    if (!best || err < best.err - 1e-6) best = { pitch: t, err };
174	  }
175	  return { yaw: Math.atan2(-dx, -dz), pitch: best ? best.pitch : Math.atan2(dy, dist), aimError: best ? round(best.err) : null };
176	}
