220	
221	  // Snapshot living entities before firing so health and knockback can be compared afterwards.
222	  const watched = new Map();
223	  for (const e of Object.values(bot.entities)) {
224	    if (e === bot.entity || dead.has(e.id) || health(e) === undefined || e.position.distanceTo(bot.entity.position) > radius) continue;
