229	  const spawned = [];
230	  const sample = () => {
231	    for (const w of watched.values()) {
232	      const v = w.entity.velocity;
233	      w.maxUpwardVelocity = Math.max(w.maxUpwardVelocity, v.y);
234	      w.maxHorizontalVelocity = Math.max(w.maxHorizontalVelocity, Math.hypot(v.x, v.z));
235	    }
236	    for (const f of spawned) {
237	      const p = f.entity;
238	      if (f.removedAt) continue;
239	      if (!bot.entities[p.id]) { f.removedAt = Date.now(); continue; }
240	      f.stuck = p.metadata?.[10] === true || p.velocity.norm() < 0.01;
241	      if (!p.position.equals(f.server)) Object.assign(f, { pos: p.position.clone(), vel: p.velocity.clone(), server: p.position.clone() });
242	      else if (!f.stuck) {
243	        f.pos = f.pos.plus(f.vel);
244	        f.vel = new Vec3(f.vel.x * 0.99, f.vel.y * 0.99 - spec.gravity, f.vel.z * 0.99);
245	      }
246	    }
247	  };
