249	  const started = Date.now();
250	  const botHealthBefore = bot.health;
251	  const ammoBefore = ammoCount();
252	  const shots = [];
253	  const onSpawn = (e) => {
254	    if (e.type === 'projectile' || /arrow|trident|snowball|egg|pearl|potion|wind_charge|experience_bottle|firework/.test(e.name || '')) {
255	      if (e.position.distanceTo(bot.entity.position) < 4) spawned.push({ entity: e, pos: e.position.clone(), vel: e.velocity.clone(), server: e.position.clone() });
256	    }
257	  };
258	  bot.on('entitySpawn', onSpawn);
259	  bot.on('physicsTick', sample);
260	  try {
261	    for (const [i, t] of targets.entries()) {
262	      const targetEntity = t.entityId != null ? entity(t.entityId) : null;
263	      const point = () => (targetEntity ? targetEntity.position.offset(0, (targetEntity.height || 1.6) * 0.5, 0) : new Vec3(...t.position));
264	      const eye = () => bot.entity.position.offset(0, (bot.entity.eyeHeight || 1.62) - 0.1, 0);
265	      let a = aim(eye(), point(), spec.speed * power, spec.gravity);
266	      await bot.look(a.yaw, a.pitch, true);
267	      const before = spawned.length;
268	      const firing = release(spec, charge);
269	      // Re-aim during the draw in case the target moved.
270	      if (spec.mode !== 'throw') {
271	        await bot.waitForTicks(Math.max(1, charge - 2));
272	        a = aim(eye(), point(), spec.speed * power, spec.gravity);
273	        await bot.look(a.yaw, a.pitch, true);
274	      }
275	      await firing;
276	      const firedAtMs = Date.now() - started;
277	      for (let k = 0; k < 6 && spawned.length === before; k++) await bot.waitForTicks(1);
278	      const flight = spawned[before] || null;
279	      const proj = flight?.entity || null;
280	      shots.push({
281	        target: targetEntity ? { entityId: targetEntity.id, name: targetEntity.name, position: vec(targetEntity.position) } : { position: t.position },
282	        aim: { pitchDeg: round((a.pitch * 180) / Math.PI), aimError: a.aimError },
283	        firedAtMs,
284	        projectile: proj ? { id: proj.id, name: proj.name, spawnVelocity: vec(proj.velocity) } : null,
285	        _flight: flight,
286	        _releasedAt: started + firedAtMs,
287	      });
288	      if (i < targets.length - 1 && intervalTicks > 0) await bot.waitForTicks(Number(intervalTicks));
289	    }
290	
291	    // Wait until every projectile has landed or been removed (or trackTicks runs out).
292	    const limit = Math.min(Math.max(Number(trackTicks) || 60, 10), 200);
293	    let settled = 0;
294	    for (let tick = 0; tick < limit && settled < 15; tick++) {
295	      await bot.waitForTicks(1);
296	      settled = spawned.some((f) => !f.removedAt && !f.stuck) ? 0 : settled + 1;
297	    }
298	    for (const s of shots) {
299	      const f = s._flight;
300	      if (f) {
301	        s.projectile.lastPosition = vec(f.pos);
302	        s.projectile.state = f.removedAt ? `removed ${f.removedAt - s._releasedAt}ms after release` : f.stuck ? 'stuck in a block' : 'still flying';
