304	      delete s._flight;
305	      delete s._releasedAt;
306	    }
307	  } finally {
308	    bot.off('entitySpawn', onSpawn);
309	    bot.off('physicsTick', sample);
310	  }
311	
312	  const seen = eventsSince(started);
313	  const explosions = seen.filter((e) => e.kind === 'explosion').map((e) => ({ atMs: e.at - started, position: e.position }));
314	  const entities = [...watched.values()].map((w) => {
315	    const died = dead.has(w.entity.id) || seen.some((e) => e.kind === 'death' && e.entityId === w.entity.id);
316	    const gone = !bot.entities[w.entity.id];
317	    return {
318	      id: w.entity.id,
319	      name: w.entity.name,
320	      healthBefore: w.healthBefore,
321	      healthAfter: died ? 0 : gone ? null : health(w.entity),
322	      died,
323	      ...(gone && !died ? { gone: 'left render range or was removed' } : {}),
324	      timesHurt: seen.filter((e) => e.kind === 'hurt' && e.entityId === w.entity.id).length,
325	      maxUpwardVelocity: round(w.maxUpwardVelocity),
326	      maxHorizontalVelocity: round(w.maxHorizontalVelocity),
327	      moved: round(w.entity.position.distanceTo(w.start)),
328	      distanceToNearestExplosion: explosions.length ? round(Math.min(...explosions.map((x) => w.start.distanceTo(new Vec3(...x.position))))) : null,
329	    };
330	  });
331	  return {
332	    item: held.name,
333	    power: round(power),
334	    ammo: spec.ammo ? { before: ammoBefore, after: ammoCount() } : undefined,
335	    shots,
336	    explosions,
337	    entities,
338	    bot: { healthBefore: botHealthBefore, healthAfter: bot.health },
339	    chat: chat.filter((c) => c.at >= started).map((c) => c.text),
340	  };
341	}
