599	function rcon(port, password, command) {
600	  return new Promise((resolve, reject) => {
601	    const sock = net.connect(port, '127.0.0.1');
602	    const packet = (id, type, body) => {
603	      const b = Buffer.from(body, 'utf8');
604	      const p = Buffer.alloc(14 + b.length);
605	      p.writeInt32LE(10 + b.length, 0);
606	      p.writeInt32LE(id, 4);
607	      p.writeInt32LE(type, 8);
608	      b.copy(p, 12);
609	      return p;
610	    };
611	    let buf = Buffer.alloc(0);
612	    let authed = false;
613	    const timer = setTimeout(() => { sock.destroy(); reject(new Error(`RCON timed out: ${command}`)); }, 10000);
614	    sock.on('connect', () => sock.write(packet(1, 3, password)));
615	    sock.on('data', (d) => {
616	      buf = Buffer.concat([buf, d]);
617	      while (buf.length >= 4) {
618	        const len = buf.readInt32LE(0);
619	        if (buf.length < len + 4) break;
620	        const id = buf.readInt32LE(4);
621	        const type = buf.readInt32LE(8);
622	        const body = buf.toString('utf8', 12, len + 2);
623	        buf = buf.subarray(len + 4);
624	        if (!authed && type === 2) {
625	          if (id === -1) { clearTimeout(timer); sock.destroy(); return reject(new Error('RCON authentication failed.')); }
626	          authed = true;
627	          sock.write(packet(2, 2, command));
628	        } else if (authed && id === 2) {
629	          clearTimeout(timer);
630	          sock.end();
631	          return resolve(body.replace(/§./g, ''));
632	        }
633	      }
634	    });
635	    sock.on('error', (e) => { clearTimeout(timer); reject(e); });
636	  });
637	}
