// Boots Benana's game runtime under plain Node and exercises the new bot tools against a real Paper server.
const root = process.argv[2];
const game = require(`${root}/electron/lib/game/index.cjs`);
const log = (k, v) => console.log(`\n== ${k}\n${JSON.stringify(v, (key, val) => (key === 'samples' ? `[${val.length} samples]` : val), 1).slice(0, 1500)}`);

(async () => {
  const t = (tool, args) => game.runTool(tool, args);
  try {
    await game.start(() => {});
    await t('reset_arena');
    await t('game_setup', { commands: [
      'give @bot heart_of_the_sea[custom_name=\'"Storm Core"\',item_model="benana:storm_core"] 2',
      'give @bot dirt 4',
      'bossbar add benana:test "Storm Golem"', 'bossbar set benana:test players @a', 'bossbar set benana:test color purple', 'bossbar set benana:test value 70',
      'title @bot actionbar "Recharging 1.2s"',
    ] });
    await t('wait_ticks', { ticks: 10 });
    const st = await t('bot_state');
    log('bot_state (items + effects)', { entityId: st.entityId, effects: st.effects, inventory: st.inventory });
    log('boss_bars', await t('boss_bars'));
    log('read_chat (action bar)', (await t('read_chat', { sinceMs: Date.now() - 5000 })));
    const plain = await t('move', { jump: true, ticks: 3 });
    log('move jump, no boost', { maxHeightGain: plain.maxHeightGain, maxUpwardVelocity: plain.maxUpwardVelocity, launches: plain.launches });
    await t('game_setup', { commands: ['effect give @bot jump_boost 10 1 true'] });
    await t('wait_ticks', { ticks: 5 });
    const boosted = await t('move', { jump: true, ticks: 3 });
    log('move jump, Jump Boost II', { maxHeightGain: boosted.maxHeightGain, maxUpwardVelocity: boosted.maxUpwardVelocity, effects: boosted.effects });
    const walk = await t('move', { forward: true, sprint: true, ticks: 20, yaw: 0 });
    log('move sprint south 20 ticks', { horizontalDistance: walk.horizontalDistance, start: walk.start, end: walk.end });
    const p = (await t('bot_state')).position;
    const spot = [Math.floor(p[0]) + 2, 65, Math.floor(p[2])];
    log('place_block', await t('place_block', { item: 'dirt', position: spot }));
    log('dig_block', await t('dig_block', { position: spot }));
    await t('equip', { item: 'heart_of_the_sea' });
    const used = await t('use_item', { position: [p[0], 64, p[2] + 10], trackSelf: 20 });
    log('use_item position + trackSelf', { used: used.used, on: used.on, maxHeightGain: used.self.maxHeightGain, chat: used.chat });
    const still = await t('track_self', { ticks: 20 });
    log('track_self idle', { launches: still.launches, maxUpwardVelocity: still.maxUpwardVelocity, health: still.health });
    await t('game_setup', { commands: ['bossbar remove benana:test'] });
  } catch (e) {
    console.error('SMOKE FAILED:', e.stack || e.message);
    process.exitCode = 1;
  } finally {
    await game.stop().catch(() => {});
    process.exit();
  }
})();

