// Boots the game with a resource pack in place and checks Paper offers it and the control server serves it.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const [root, zipPath] = process.argv.slice(2);
const { dir } = require(`${root}/electron/lib/game/server.cjs`);
const game = require(`${root}/electron/lib/game/index.cjs`);
const packFile = path.join(dir, 'studio-pack.zip');

(async () => {
  const had = fs.existsSync(packFile);
  if (had) throw new Error('A studio pack is already deployed; not touching it.');
  fs.copyFileSync(zipPath, packFile);
  const logs = [];
  try {
    await game.start((ch, d) => ch === 'game:log' && logs.push(d.line));
    const props = fs.readFileSync(path.join(dir, 'server.properties'), 'utf8').split('\n').filter((l) => l.startsWith('resource-pack') || l.startsWith('require-resource'));
    console.log(props.join('\n'));
    const url = props.find((l) => l.startsWith('resource-pack=')).slice('resource-pack='.length).replace(/\\:/g, ':');
    const body = Buffer.from(await (await fetch(url)).arrayBuffer());
    const sha1 = crypto.createHash('sha1').update(body).digest('hex');
    console.log('served bytes', body.length, 'sha1 matches', props.some((l) => l === `resource-pack-sha1=${sha1}`));
    console.log('pack-related log lines:', logs.filter((l) => /resource|pack/i.test(l)));
  } catch (e) {
    console.error('SMOKE FAILED:', e.message);
    process.exitCode = 1;
  } finally {
    await game.stop().catch(() => {});
    fs.rmSync(packFile, { force: true });
    process.exit();
  }
})();
